def cases():
    return json.loads(json.dumps(CASES))

def paired(p):
    return [(float(x),float(y)) for x,y in zip(p['t'],p['y'])
            if x is not None and y is not None and math.isfinite(float(x)) and math.isfinite(float(y))]

def mathematical(row, *, allow_boundary=True):
    with mp.workdps(70):
        p=row['parameters']; xy=paired(p)
        t=[mp.mpf(str(x)) for x,y in xy]; y=mp.matrix([mp.mpf(str(y)) for x,y in xy]); n=len(t)
        def profile(period):
            w=2*mp.pi/period
            X=mp.matrix([[1,mp.cos(w*x),mp.sin(w*x)] for x in t])
            beta=mp.lu_solve(X.T*X,X.T*y)
            residual=y-X*beta
            d=mp.matrix([[(2*mp.pi*x/period**2)*(beta[1]*mp.sin(w*x)-beta[2]*mp.cos(w*x))] for x in t])
            return sum(v*v for v in residual), -2*(residual.T*d)[0], X,beta,residual,d
        period=mp.mpf(str(p['period']))
        if p['period_free']:
            lo,hi=map(lambda v:mp.mpf(str(v)),p['free_bounds'])
            grid=[lo+(hi-lo)*i/160 for i in range(161)]
            roots=[]
            previous=profile(grid[0])[1]
            for a,b in zip(grid,grid[1:]):
                current=profile(b)[1]
                if previous<0<current:
                    roots.append(mp.findroot(lambda v:profile(v)[1],(a,b),solver='anderson',tol=mp.mpf('1e-60')))
                previous=current
            period=min([lo,hi,*roots],key=lambda v:profile(v)[0])
            if period in (lo,hi) and not allow_boundary:
                raise ValueError('Boundary uncertainty requires separate contract')
        sse,_,X,beta,residual,d=profile(period)
        M,b,g=beta
        if abs(b)<mp.mpf('1e-60'): b=mp.mpf(0)
        if abs(g)<mp.mpf('1e-60'): g=mp.mpf(0)
        if sse<mp.mpf('1e-60'): sse=mp.mpf(0)
        amp=mp.sqrt(b*b+g*g)
        phase=(mp.atan2(g,b)%(2*mp.pi))*period/(2*mp.pi) if amp else mp.nan
        mean=sum(y)/n; tss=sum((v-mean)**2 for v in y)
        k=4 if p['period_free'] else 3; numerator=k-1; df=n-k
        r2=1-sse/tss if tss else mp.nan
        F=(max(tss-sse,mp.mpf(0))/numerator)/(sse/df) if sse else (mp.inf if tss else mp.nan)
        probability=mp.betainc(mp.mpf(df)/2,mp.mpf(numerator)/2,0,df/(df+numerator*F),regularized=True) if mp.isfinite(F) else (mp.mpf(0) if F==mp.inf else mp.nan)
        J=mp.matrix([[X[i,j] for j in range(3)]+([d[i]] if k==4 else []) for i in range(n)])
        at_boundary=p['period_free'] and period in (lo,hi)
        cov=mp.matrix([[mp.nan]*k for _ in range(k)]) if at_boundary else (sse/df)*(J.T*J)**-1
        seM=mp.sqrt(cov[0,0]); seA=sePhi=mp.nan
        if amp:
            a=mp.matrix([0,b/amp,g/amp]+([0] if k==4 else []))
            phi=mp.matrix([0,-g/(amp**2)*period/(2*mp.pi),b/(amp**2)*period/(2*mp.pi)]+([phase/period] if k==4 else []))
            seA=mp.sqrt((a.T*cov*a)[0]); sePhi=mp.sqrt((phi.T*cov*phi)[0])
        result=[n,period,M,amp,phase,b,g,seM,seA,sePhi]
        if k==4: result.append(mp.sqrt(cov[3,3]))
        result.extend([r2,F,probability,probability])
        result.extend(M+b*mp.cos(2*mp.pi*mp.mpf(str(x))/period)+g*mp.sin(2*mp.pi*mp.mpf(str(x))/period) for x in p['prediction_t'])
        return [float(v) for v in result]

def production(row):
    from PyFLASH.stats_extra import fit_cosinor
    p=row['parameters']
    kwargs={k:v for k,v in p.items() if k not in ['t','y','prediction_t']}
    if row.get('omit_bounds'): kwargs.pop('free_bounds',None)
    if row.get('omit_period'): kwargs.pop('period',None)
    answer=fit_cosinor([float('nan') if x is None else float(x) for x in p['t']],
                       [float('nan') if x is None else float(x) for x in p['y']],**kwargs)
    result=[answer[k] for k in ['n','period','mesor','amplitude','acrophase','coef_cos','coef_sin']]
    result.extend(answer['params'][k]['stderr'] for k in ['mesor','amplitude','acrophase'])
    if p['period_free']: result.append(answer['params']['period']['stderr'])
    result.extend(answer[k] for k in ['r_squared','f_stat','p','p_rhythm'])
    result.extend(answer['predict'](p['prediction_t']).tolist())
    return result

def r_vector(xs):
    return 'c('+','.join(format(x,'.17g') for x in xs)+')'

def free_query(row):
    p=row['parameters']; xy=paired(p); lo,hi=p['free_bounds']
    return f'''local({{
      t<-{r_vector([x for x,y in xy])}; y<-{r_vector([y for x,y in xy])};
      lo<-{lo}; hi<-{hi}; n<-length(y);
      prof<-function(per){{
        w<-2*pi/per; X<-cbind(1,cos(w*t),sin(w*t)); fit<-lm.fit(X,y);
        b<-fit$coefficients; residual<-fit$residuals;
        d<-(2*pi*t/per^2)*(b[2]*sin(w*t)-b[3]*cos(w*t));
        list(sse=sum(residual^2),gradient=-2*sum(residual*d),beta=b,X=X,d=d)
      }};
      grid<-seq(lo,hi,length.out=161); grads<-sapply(grid,function(x)prof(x)$gradient);
      roots<-c();
      for(i in seq_len(160)){{
        if(grads[i]<0 && grads[i+1]>0){{
          roots<-c(roots,uniroot(function(x)prof(x)$gradient,c(grid[i],grid[i+1]),tol=1e-12)$root)
        }}
      }};
      candidates<-c(lo,hi,roots); per<-candidates[which.min(sapply(candidates,function(x)prof(x)$sse))];
      fit<-prof(per); b<-fit$beta; M<-b[1]; amp<-sqrt(b[2]^2+b[3]^2);
      peak<-(atan2(b[3],b[2]) %% (2*pi))*per/(2*pi);
      J<-cbind(fit$X,fit$d); cov<-if(per==lo || per==hi) matrix(NA_real_,4,4) else fit$sse/(n-4)*solve(crossprod(J));
      a<-c(0,b[2]/amp,b[3]/amp,0);
      phase<-c(0,-b[3]*per/(2*pi*amp^2),b[2]*per/(2*pi*amp^2),peak/per);
      tss<-sum((y-mean(y))^2); F<-((tss-fit$sse)/3)/(fit$sse/(n-4));
      probability<-pf(F,3,n-4,lower.tail=FALSE);
      pred_t<-{r_vector(p['prediction_t'])};
      predicted<-M+b[2]*cos(2*pi*pred_t/per)+b[3]*sin(2*pi*pred_t/per);
      c(n,per,M,amp,peak,b[2],b[3],sqrt(cov[1,1]),sqrt(drop(t(a)%*%cov%*%a)),
        sqrt(drop(t(phase)%*%cov%*%phase)),sqrt(cov[4,4]),1-fit$sse/tss,F,probability,probability,predicted)
    }})'''

def native_queries(rows):
    check_sources()
    files=[ROOT/'cosinor.lm.R',ROOT/'summary.cosinor.lm.R',ROOT/'cosinor2/cosinor2.R']
    source='\n'.join(f.read_text(encoding='utf-8') for f in files)
    chunks=[source[i:i+3000] for i in range(0,len(source),3000)]
    setup='eval(parse(text=paste0('+','.join(json.dumps(c,ensure_ascii=True) for c in chunks)+')),envir=.GlobalEnv); 1'
    queries=[{'key':'published-source-setup','code':setup}]
    for row in rows:
        p=row['parameters']
        if row['reference_kind']!='published-fixed':
            continue
        xy=paired(p); period=p['period']; prediction=p['prediction_t']
        expression=f'''local({{
          t<-{r_vector([x for x,y in xy])}; y<-{r_vector([y for x,y in xy])}; per<-{period}; w<-2*pi/per;
          fit<-cosinor.lm(y~time(t),period=per,data=data.frame(t=t,y=y));
          s<-summary.cosinor.lm(fit); b<-coef(fit$fit)[2]; g<-coef(fit$fit)[3];
          peak<-(-correct.acrophase(fit)/w) %% per; det<-cosinor.detect(fit);
          pred<-predict(fit$fit,newdata=data.frame(rrr=cos(w*{r_vector(prediction)}),sss=sin(w*{r_vector(prediction)})));
          c(length(t),per,coef(fit$fit)[1],s$transformed.table$estimate[2],peak,b,g,
            s$transformed.table$standard.error[1:2],s$transformed.table$standard.error[3]/w,
            summary(fit$fit)$r.squared,det[1],det[4],det[4],pred)
        }})'''
        queries.append({**row,'code':expression})
    return queries + [{**row,'code':free_query(row)} for row in rows if row['parameters']['period_free']]

def check_sources():
    catalogue=json.loads((SOURCE_ROOT/'sources.json').read_text())
    for name,row in catalogue['files'].items():
        if hashlib.sha256((SOURCE_ROOT/name).read_bytes()).hexdigest()!=row['sha256']:
            raise ValueError('Published cosinor source changed: '+name)
    return catalogue

def execute(output):
    queries=native_queries(cases())
    if FIXTURE.exists():
        fixture=json.loads(FIXTURE.read_text())
        if check_sources()!=fixture['sources']:
            raise ValueError('Published cosinor source identity changed')
        for actual,expected in zip(queries,fixture['native']['rows'],strict=True):
            if actual!={key:expected[key] for key in actual}:
                raise ValueError('Frozen cosinor expression or input changed')
    result=execute_queries(queries,output,name='cosinor-full-contract')
    if FIXTURE.exists():
        for key in ['R','webR','wasm_sha256']:
            if result[key]!=fixture['native'][key]:
                raise ValueError('Cosinor reference runtime changed: '+key)
    return result

def packed(numbers):
    return {'values':[v if math.isfinite(v) else None for v in numbers],
        'nonfinite':[None if math.isfinite(v) else 'positive_infinity' if v==math.inf
            else 'negative_infinity' if v==-math.inf else 'nan' for v in numbers]}
